import fs from 'node:fs/promises';
import { chromium } from 'playwright';

const BASE='https://www.statesideqm.com';
const THEME='158561894555';
const NAME=process.env.SQ_ROUTE_NAME;
const ROUTE=process.env.SQ_ROUTE;
const EXPECT_FIX=process.env.SQ_ROUTE_FIX||'';
const FALSE_HANDLES=new Set((process.env.SQ_FALSE_HANDLES||'').split(',').filter(Boolean));
const out='cert-v3-route-v2';
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function target(){const u=new URL(ROUTE,BASE);u.searchParams.set('preview_theme_id',THEME);return u.toString()}
async function nav(page){let last;for(let i=0;i<4;i++){try{const r=await page.goto(target(),{waitUntil:'domcontentloaded',timeout:40000});const status=r?.status()||0;if(status===200){await delay(900);return status}last=new Error('HTTP '+status);if(![429,500,502,503,504].includes(status))break}catch(e){last=e}await delay(1600*(i+1))}throw last||new Error('navigation failed')}
async function ready(page){await page.waitForFunction(expect=>{const m=document.querySelector('#MainContent');if(m?.dataset.sqRefineV3Error)return true;return m?.dataset.sqRefineV3Ready==='true'&&(!expect||m?.dataset.sqRefineV3RouteFix===expect)},EXPECT_FIX,{timeout:45000});const err=await page.locator('#MainContent').getAttribute('data-sq-refine-v3-error');if(err)throw new Error('V3 '+err)}
async function inspect(page,mobile){return page.evaluate(({falseHandles,mobile})=>{const vis=el=>{if(!el)return false;const s=getComputedStyle(el),r=el.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)!==0&&r.width>0&&r.height>0};const handle=raw=>{try{const m=new URL(raw,location.origin).pathname.match(/^\/collections\/([^/?#]+)/);return m?decodeURIComponent(m[1]):''}catch{return''}};const main=document.querySelector('#MainContent'),side=main?.querySelector('.sq-refine-v3-sidebar'),size=main?.querySelector('.sq-refine-v3-page-size'),grid=main?.querySelector('.product-grid');const groups=side?[...side.querySelectorAll('.sq-refine-v3-group')]:[];const structural=side?[...side.querySelectorAll('input[data-kind="structural"]')].map(i=>({label:i.closest('label')?.innerText.trim()||'',target:i.dataset.target||'',handle:handle(i.dataset.target||'')})):[];const native=side?[...side.querySelectorAll('input[data-kind="native"]')].map(i=>i.dataset.filterName||''):[];const sizes=size?[...size.querySelectorAll('input')].map(i=>({value:i.value,checked:i.checked})):[];const cards=grid?[...grid.querySelectorAll(':scope>.product-grid__item')].filter(x=>x.querySelector('a[href*="/products/"]')).length:0;const columns=grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0;const oldSel='[data-sq-global-refine-products],.sq-refine-taxonomy-products,[data-sq-filtered-product-surface-guard-products],[data-sq-military-filtered-products],[data-sq-category-universe-products],[data-sq-custom-color-products]';const oldVisible=[...document.querySelectorAll(oldSel)].filter(vis).length;const hiddenVisible=[...document.querySelectorAll('[data-sq-refine-v3-hidden-nav="true"]')].filter(vis).length;const ss=side?getComputedStyle(side):null,sr=side?.getBoundingClientRect();return{ready:main?.dataset.sqRefineV3Ready||'',routeFix:main?.dataset.sqRefineV3RouteFix||'',sidebarVisible:vis(side),title:side?.querySelector('.sq-refine-v3-sidebar__title')?.textContent.trim()||'',pageSizeVisible:vis(size),pageSizeInsideSidebar:!!size?.closest('.sq-refine-v3-sidebar'),sizes,groups:groups.map(g=>({label:g.querySelector(':scope>summary')?.textContent.trim()||'',open:g.open,checked:g.querySelectorAll('input:checked').length,inputs:g.querySelectorAll('input[type="checkbox"]').length})),structural,native,falseStructural:structural.filter(x=>falseHandles.includes(x.handle)),gridVisible:vis(grid),columns,cards,sidebarPosition:ss?.position||'',sidebarHeight:sr?.height||0,oldVisible,hiddenVisible,mobile};},{falseHandles:[...FALSE_HANDLES],mobile})}
async function toggle(page){const picked=await page.evaluate(()=>{const d=[...document.querySelectorAll('.sq-refine-v3-sidebar .sq-refine-v3-group')].find(x=>!x.open);if(!d)return false;d.setAttribute('data-sq-cert-toggle-target','true');return true});if(!picked)return{pass:true,reason:'no inactive group'};const d=page.locator('[data-sq-cert-toggle-target="true"]');const s=d.locator(':scope>summary');await s.scrollIntoViewIfNeeded();const before=await s.evaluate(el=>getComputedStyle(el,'::after').content);let click1='',click2='';try{await s.click({timeout:7000})}catch(e){click1=String(e)}await delay(150);const opened=await d.evaluate(el=>el.open);const afterOpen=await s.evaluate(el=>getComputedStyle(el,'::after').content);try{await s.click({timeout:7000})}catch(e){click2=String(e)}await delay(150);const closed=await d.evaluate(el=>!el.open);const afterClose=await s.evaluate(el=>getComputedStyle(el,'::after').content);return{pass:/\+/.test(before)&&opened&&/[−\u2212-]/.test(afterOpen)&&closed&&/\+/.test(afterClose)&&!click1&&!click2,before,opened,afterOpen,closed,afterClose,click1,click2}}
function errors(d,t,mobile){const e=[];if(d.ready!=='true')e.push('V3 not ready');if(EXPECT_FIX&&d.routeFix!==EXPECT_FIX)e.push('route fix marker missing');if(!d.sidebarVisible)e.push('sidebar hidden');if(d.title!=='Refine Products')e.push('bad title');if(!d.pageSizeVisible||d.pageSizeInsideSidebar)e.push('bad page-size placement');if(d.sizes.map(x=>x.value).join(',')!=='50,100,250'||!d.sizes.find(x=>x.value==='50')?.checked)e.push('bad page-size options/default');if(!d.groups.length)e.push('no refine groups');for(const g of d.groups){if(!g.inputs)e.push('empty group '+g.label);if(!g.checked&&g.open)e.push('inactive group open '+g.label);if(g.checked&&!g.open)e.push('active group closed '+g.label)}if(d.groups.some(g=>/color\s*[\/&+]\s*pattern|color and pattern/i.test(g.label)))e.push('combined Color/Pattern');if(d.falseStructural.length)e.push('unrelated structural links: '+d.falseStructural.map(x=>x.handle).join(','));if(d.oldVisible)e.push('old product surface visible');if(d.hiddenVisible)e.push('old navigation visible');if(!d.gridVisible)e.push('product grid hidden');if(d.gridVisible&&d.columns!==(mobile?2:3))e.push(`${mobile?'mobile':'desktop'} columns=${d.columns}`);if(mobile){if(d.sidebarPosition==='sticky')e.push('mobile sidebar sticky')}else{if(d.sidebarPosition!=='sticky')e.push('sidebar not sticky');if(d.sidebarHeight<600)e.push('sidebar too short')}if(!d.cards)e.push('no product cards');if(d.native.some(n=>!n.startsWith('filter.')))e.push('bad native filter');if(!t.pass)e.push('plus/minus toggle failed');return e}
async function run(viewport,label,mobile){const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport});const page=await ctx.newPage();const row={};try{row.http=await nav(page);await ready(page);row.data=await inspect(page,mobile);row.toggle=await toggle(page);row.errors=errors(row.data,row.toggle,mobile);await page.screenshot({path:`${out}/${label}.png`,fullPage:true})}catch(e){row.errors=[String(e)];try{await page.screenshot({path:`${out}/${label}-error.png`,fullPage:true})}catch{}}await ctx.close();await browser.close();return row}
await fs.mkdir(out,{recursive:true});
const desktop=await run({width:1440,height:1000},'desktop',false);
const mobile=await run({width:390,height:844},'mobile',true);
const report={name:NAME,route:ROUTE,desktop,mobile,pass:!(desktop.errors?.length||mobile.errors?.length)};
await fs.writeFile(`${out}/report.json`,JSON.stringify(report,null,2));
console.log(JSON.stringify({name:NAME,pass:report.pass,desktop:desktop.errors||[],mobile:mobile.errors||[],desktopData:desktop.data,mobileData:mobile.data},null,2));
if(!report.pass)process.exitCode=1;
